<template>
	<view class="success" v-show="info.orderNo">
		<!-- 报名成功 -->
		<view class="success-box">
			<view class="img-box">
				<image src="/static/images/success.png" mode="widthFix"></image>
			</view>
			<view class="success-title">报名成功!</view>
			<view class="success-tex" v-if="info.status > 4">管理员已分配学习账号</view>
			<view class="success-tex" v-else>支付已完成，请等待管理员分配学习账号</view>
		</view>

		<!-- 订单详情 -->
		<view class="order-box">
			<view class="order-title">
				<text></text>订单详情
			</view>
			<view class="grade-list">
				<view class="grade-cont">
					<view class="grade-tex">订单编号</view>
					<view class="grade-desc">{{info.orderNo}}</view>
				</view>
				<view class="grade-cont">
					<view class="grade-tex">报名课程</view>
					<view class="grade-desc">{{courseArray.join('、')}}</view>
				</view>
				<view class="grade-cont">
					<view class="grade-tex">报名校区</view>
					<view class="grade-desc">{{schoolArray.join('、')}}</view>
				</view>
				<view class="grade-cont">
					<view class="grade-tex">支付金额</view>
					<view class="grade-desc">
						<text class="price">¥{{info.payAmount}}</text>
						<text class="yuanjia">¥{{info.totalAmount}}</text>
						<text class="youhui">已优惠¥{{info.couponAmount}}</text>
					</view>
				</view>
				<view class="grade-cont">
					<view class="grade-tex">支付时间</view>
					<view class="grade-desc">{{info.payTime}}</view>
				</view>
				<view class="grade-cont">
					<!-- 0待支付 1已支付 2已取消 3已审核 4待分配 5已完成 -->
					<view class="grade-tex">订单状态</view>
					<view class="grade-desc">{{info.status > 4 ? '已分配账号' : '等待分配账号'}}</view>
				</view>
			</view>
		</view>

