				<text class="acc-value">{{info.account}}</text>
				<text class="acc-btn" @click="copy(info.account)">复制</text>
			</view>
			<view class="acc-label">登录密码</view>
			<view class="acc-item">
				<text class="iconfont icon-mima3"></text>
				<text class="acc-value">{{info.password}}</text>
				<text class="acc-btn" @click="copy(info.password)">复制</text>
			</view>
