						<text class="iconfont icon-duigou"></text>
					</view>
					<view class="step-tex">待分配</view>
				</view>
				<view class="step-item" :class="{active:info.status > 4}">
					<view class="step-num">
						<text class="iconfont icon-duigou" v-if="info.status > 4"></text>
						<text class="num" v-else>03</text>
					</view>
					<view class="step-tex">已分配</view>
				</view>
				<view class="step-left active"></view>
				<view class="step-right"></view>
			</view>
		</view>


