<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo,
		copyText,
		reLaunch,
		switchTabTo
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		queryOrderDetail
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				orderId: '',
				courseArray: [],
				schoolArray: [],
				info: {},
			};
		},
		computed: {
			paddingbottom() {
				const res = wx.getSystemInfoSync()
				const {
					screenHeight,
					safeArea: {
						bottom
					}
				} = res
				if (screenHeight && bottom) {
					let safeBottom = screenHeight - bottom
					return safeBottom
				} else {
					return 0
				}
			}
		},
		components: {

		},
		onLoad(options) {
			this.orderId = options.orderId
			this.init()
		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {

			copy(text) {
				copyText(text)
			},

			async init() {
				this.showLoading = true
				let _data = await queryOrderDetail(this.orderId);
				if (_data.code == 200) {
					this.showLoading = false
					this.info = _data.data
					this.info.itemList.map(item => {
						this.courseArray.push(item.courseTitle)
						this.schoolArray.push(item.campusName)
					})

					this.schoolArray = [...new Set(this.schoolArray)]
				}
			},

			to(path) {
				switchTabTo(path)
			},
		},

	}
</script>

